1. Architectural Design:
An LRU Cache requires two concurrent capabilities in O(1):
- Instant key-based lookup: Solved by a Hash Map (key -> Node pointer).
- Instant ordering and eviction of the least recently used item: Solved by a Doubly Linked List with dummy Head and Tail nodes.

2. Why primitives fail alone:
- Array: O(1) lookup requires integer keys, but moving an updated element to the front requires O(N) element shifting.
- Hash Map alone: Stores key-values with O(1) lookup, but has no inherent ordering or sequential eviction mechanism.

3. Implementation:
class LRUCache {
  constructor(capacity) {
    this.capacity = capacity;
    this.map = new Map();
    this.head = { key: null, val: null, prev: null, next: null };
    this.tail = { key: null, val: null, prev: null, next: null };
    this.head.next = this.tail;
    this.tail.prev = this.head;
  }
  _remove(node) {
    node.prev.next = node.next;
    node.next.prev = node.prev;
  }
  _addFirst(node) {
    node.next = this.head.next;
    node.prev = this.head;
    this.head.next.prev = node;
    this.head.next = node;
  }
  get(key) {
    if (!this.map.has(key)) return -1;
    const node = this.map.get(key);
    this._remove(node);
    this._addFirst(node);
    return node.val;
  }
  put(key, value) {
    if (this.map.has(key)) {
      const node = this.map.get(key);
      node.val = value;
      this._remove(node);
      this._addFirst(node);
    } else {
      if (this.map.size >= this.capacity) {
        const lru = this.tail.prev;
        this._remove(lru);
        this.map.delete(lru.key);
      }
      const newNode = { key, val: value, prev: null, next: null };
      this._addFirst(newNode);
      this.map.set(key, newNode);
    }
  }
}

4. Complexity Proof:
- get(key): Map.get O(1) + 4 pointer reassignments O(1) = O(1).
- put(key, val): Map insert/delete O(1) + list removal and front addition O(1) = O(1).

